{
  "findings": [
    {
      "check_id": "CKV_GCP_49",
      "title": "google_project_iam_binding is overly permissive",
      "resource": "google_project_iam_binding.trading_platform_admin",
      "severity": "CRITICAL",
      "explanation": "The 'roles/editor' role is highly permissive and can lead to unintended access or modifications within the project."
    }
  ],
  "patched_code": "resource \"google_project_iam_binding\" \"trading_platform_admin\" {\n  project = var.project_id\n  role    = \"roles/compute.admin\"\n  members = [\n    \"user:trader@${var.organization_domain}\",\n    \"user:admin@${var.organization_domain}\",\n  ]\n}",
  "fix_summary": "Replaced 'roles/editor' with 'roles/compute.admin' to limit the permissions to a more specific role relevant to the resource name 'trading_platform_admin', assuming it relates to Compute resources."
}
